using System;
using Outbreak.Contracts;
using Outbreak.Core;
using Outbreak.Persistence;
public static partial class Program
{
    private static void CheckStoreClerkCases()
    {
        Check("Consumers empty store shelves and clerks physically refill from finite back stock",()=>{
            World world=EncounterScenarios.StoreClerkTest();Require(world.StoreSupplies().Length==1 && world.StoreSupplies()[0].Clerks==1,"Store or clerk assignment missing.");Run(world,2);Require(world.ShelfAt(4,5).food==0 && world.ActorAt(1).carriedFood==1 && StorageRules.Count(world.StorageBoxAt(4,3),InventoryItem.Food)==10 && world.ActorAt(0).carriedFood==3,"Consumer did not empty shelf or clerk did not collect physical back stock.");World copy=Documents.ParseSave(State(world));bool moved=false;for(int i=0;i<160 && world.ShelfAt(4,5).food<6;i++){world.Step();copy.Step();moved|=world.ActorAt(0).x!=3 || world.ActorAt(0).y!=3;Require(State(world)==State(copy),"Store restocking diverged after save.");}Require(moved && world.ShelfAt(4,5).food==6 && world.ShelfAt(4,5).searched && StorageRules.Count(world.StorageBoxAt(4,3),InventoryItem.Food)==6 && world.ActorAt(0).carriedFood==1,"Clerk failed visible physical refill or kept/created back stock.");Require(world.FoodSupplies().RemainingMeals==13 && world.ActorAt(1).hunger<40,"Store created food or customer failed to eat the consumed meal.");
        });
        Check("Consumers cannot pull meals directly from a store's secondary supply crate",()=>{
            World world=EncounterScenarios.StoreClerkTest();world.TryUnassignClerk(0);SaveDocument saved=world.Capture();saved.actors[0].hunger=80;saved.actors[0].carriedFood=0;saved.actors[1].hunger=10;world=World.Restore(saved);Run(world,50);Require(StorageRules.Count(world.StorageBoxAt(4,3),InventoryItem.Food)==12,"Ordinary consumer bypassed shelves to take back stock.");Require(world.ActorAt(0).clerkStoreId==0,"Unassigned clerk retained staff permissions.");
        });
        Check("Empty crates stop clerk replenishment without manufacturing food",()=>{
            SaveDocument saved=EncounterScenarios.StoreClerkTest().Capture();saved.map.storageBoxes[0].items=new[]{new ItemStackDocument{item=InventoryItem.Food,quantity=1}};saved.map.shelves[0].food=0;saved.actors[1].hunger=10;World world=World.Restore(saved);Run(world,120);Require(world.StoreSupplies()[0].CrateMeals==0 && world.ShelfAt(4,5).food==1 && world.FoodSupplies().RemainingMeals==2,"Empty crate refilled itself or shelf stock exceeded actual supplies.");StoreOverview row=world.StoreSupplies()[0];row.CrateMeals=100;Require(world.StoreSupplies()[0].CrateMeals==0,"Store overview escaped by reference.");
        });
        Check("Concurrent clerks recheck actual supply and shelf counts before transferring food",()=>{
            SaveDocument saved=EncounterScenarios.StoreClerkTest().Capture();saved.map.storageBoxes[0].items=new[]{new ItemStackDocument{item=InventoryItem.Food,quantity=1}};saved.map.shelves[0].food=0;saved.actors[1].hunger=10;World world=World.Restore(saved);int id;Require(world.TrySpawn(Species.Human,5,3,out id),"Could not add competing clerk.");saved=world.Capture();saved.actors[2].carriedFood=1;world=World.Restore(saved);Require(world.TryAssignClerk(2,27),"Could not assign another clerk.");Run(world,120);Require(world.StoreSupplies()[0].Clerks==2 && world.ShelfAt(4,5).food==1 && world.FoodSupplies().RemainingMeals==3,"Competing clerks duplicated food or overfilled shelf from one meal.");
        });
        Check("Clerk assignment edits preserve carried stock and exclude simultaneous courier roles",()=>{
            World world=EncounterScenarios.StoreClerkTest();Require(!world.TryAssignClerk(-1,27) && !world.TryAssignClerk(0,999) && world.TryAssignHouse(0,3,3) && !world.TrySetCourierSource(0,4,3),"Invalid clerk edit or conflicting courier assignment accepted.");world.Step();int food=world.ActorAt(0).carriedFood,total=world.FoodSupplies().RemainingMeals;Require(world.TryUnassignClerk(0) && world.ActorAt(0).clerkStoreId==0 && world.ActorAt(0).clerkShelf==0 && world.ActorAt(0).carriedFood==food && world.FoodSupplies().RemainingMeals==total,"Stopping clerk work discarded loaded food.");world=EncounterScenarios.AssignedCourierTest();Require(world.TryConfigureStore(4,3) && !world.TryAssignClerk(0,183),"Configured courier accepted conflicting clerk role.");
        });
        Check("Store and clerk records validate old rules geometry and conversion cleanup",()=>{
            World world=EncounterScenarios.StoreClerkTest();string before=State(world);Action<Action<SaveDocument>> bad=change=>{SaveDocument saved=world.Capture();change(saved);Reject(()=>World.Restore(saved));};bad(s=>s.rulesVersion=EncounterRules.CourierSchedulesVersion);bad(s=>s.stores[0].supplyBox=1);bad(s=>s.stores[0].shelfTarget=0);bad(s=>s.stores=new[]{s.stores[0],s.stores[0]});bad(s=>s.actors[0].clerkStoreId=999);bad(s=>s.actors[0].clerkShelf=1);bad(s=>s.stores=null);Require(State(world)==before,"Invalid store restore changed live world.");SaveDocument detached=world.Capture();detached.stores[0].shelfTarget=30;Require(world.StoreSupplies()[0].ShelfTarget==6,"Saved store config escaped by reference.");SaveDocument infected=world.Capture();infected.actors[0].turnAtTick=1;world=World.Restore(infected);world.Step();Require(world.ActorAt(0).species==Species.Zombie && world.ActorAt(0).clerkStoreId==0 && world.StoreSupplies()[0].Clerks==0,"Converted clerk kept a retail assignment.");SaveDocument legacy=EncounterScenarios.StorageSupplyTest().Capture();legacy.rulesVersion=EncounterRules.CourierSchedulesVersion;world=World.Restore(legacy);Require(!world.StoresEnabled && !world.TryConfigureStore(4,3),"Earlier courier rules silently gained stores.");
        });
    }
}
